    public static int ftPutHex4(emon.Port.Cells out, int v) {
        // Four upper-case hex digits of v, as bytes.
        int p = 4096;
        int d = 0;
        while (p > 0) {
            d = (v / p) % 16;
            if (d < 10) {
                emon.Port.cellsPush(out, 48 + d);
            } else {
                emon.Port.cellsPush(out, 55 + d);
            }
            p = p / 16;
        }
        return 0;
    }
    public static int ftPutEntry(emon.Port.Cells out, int code, int dst) {
        // `<code> <dst>` and a newline.
        emon.Port.cellsPush(out, 60);
        ftPutHex4(out, code);
        emon.Port.cellsPush(out, 62);
        emon.Port.cellsPush(out, 32);
        emon.Port.cellsPush(out, 60);
        ftPutHex4(out, dst);
        emon.Port.cellsPush(out, 62);
        emon.Port.cellsPush(out, 10);
        return 0;
    }
